insert into public.recipes (
  id, name, blurb, cuisine, source, cook_time_minutes,
  servings, hue, tags, one_pan, make_ahead, added_at, ingredients, steps
) values
  ('chana-masala', 'Chana Masala', 'A pantry curry that tastes like it took considerably longer than it did.', 'indian', '{"type":"blog","label":"smittenkitchen.com"}'::jsonb, 45, 4, 32, array['weeknight', 'vegetarian']::text[], true, true, '2026-06-11', '[{"quantity":2,"unit":"can","item":"chickpeas","category":"pantry"},{"quantity":1,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":4,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":3,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":2,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":2,"unit":"tsp","item":"ground coriander","category":"spices"},{"quantity":1,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":0.5,"unit":"tsp","item":"ground turmeric","category":"spices"},{"quantity":1,"unit":"whole","item":"lemon","category":"produce"},{"quantity":0.5,"unit":"bunch","item":"cilantro","category":"produce"}]'::jsonb, '["Cook the finely diced onion in the oil over medium heat far longer than feels necessary â€” 12 minutes, until it is genuinely brown at the edges. This is where the depth comes from.","Add the grated garlic and ginger and cook until the raw smell goes, about a minute.","Add the cumin, coriander, and turmeric and stir constantly for thirty seconds so they toast without catching.","Pour in the tomatoes and cook until the oil separates and pools at the edge of the pan. Do not rush this.","Add the drained chickpeas with a splash of water and simmer 15 minutes, mashing a handful against the side to thicken the sauce.","Finish off the heat with garam masala, lemon juice, and torn cilantro. Better still the next day."]'::jsonb),
  ('dal-makhani', 'Dal Makhani', 'Hours of low heat and an unapologetic amount of butter. Better on day two.', 'indian', '{"type":"youtube","label":"YouTube"}'::jsonb, 165, 6, 22, array['weekend', 'comfort', 'vegetarian']::text[], true, true, '2026-04-27', '[{"quantity":1.5,"unit":"cup","item":"whole black urad dal","category":"pantry"},{"quantity":0.25,"unit":"cup","item":"red kidney beans","category":"pantry"},{"quantity":4,"unit":"tbsp","item":"unsalted butter","category":"dairy"},{"quantity":0.5,"unit":"cup","item":"heavy cream","category":"dairy"},{"quantity":1,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":6,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":1,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":1,"unit":"tsp","item":"Kashmiri chilli powder","category":"spices"}]'::jsonb, '["Soak the urad dal and kidney beans together overnight in plenty of cold water. There is no shortcut worth taking here.","Drain, cover with fresh water, and simmer 60 to 75 minutes until the dal collapses when pressed against the side of the pot.","Meanwhile, cook the diced onion in half the butter until deeply golden, then add the grated garlic and ginger.","Stir in the cumin and chilli powder, then the tomatoes. Cook down until the mixture darkens and the fat separates.","Tip the cooked dal in with its liquid. Simmer uncovered on the lowest heat you can manage for a further hour, stirring now and then so it does not catch.","Whisk in the cream and remaining butter, then the garam masala. It should be loose enough to pour, not stiff.","Rest it overnight if you can. The difference is not subtle."]'::jsonb),
  ('palak-paneer', 'Palak Paneer', 'Blanch the spinach, do not boil it. That is the whole trick to the colour.', 'indian', '{"type":"youtube","label":"YouTube"}'::jsonb, 40, 4, 128, array['weeknight', 'vegetarian']::text[], false, false, '2026-07-30', '[{"quantity":1,"unit":"lb","item":"baby spinach","category":"produce"},{"quantity":14,"unit":"oz","item":"paneer","category":"dairy"},{"quantity":1,"unit":"medium","item":"yellow onion","category":"produce"},{"quantity":4,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":2,"unit":"whole","item":"green chillies","category":"produce"},{"quantity":3,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":0.25,"unit":"cup","item":"heavy cream","category":"dairy"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":1,"unit":"tsp","item":"garam masala","category":"spices"}]'::jsonb, '["Blanch the spinach in boiling water for exactly 60 seconds, then plunge it into ice water. Skipping the ice bath is why most palak paneer turns army green.","Squeeze the spinach dry and blend with the green chillies to a coarse purÃ©e â€” not a smooth one.","Cube the paneer and fry it in a little oil until the edges catch. Move it to a bowl of warm salted water so it stays soft.","In the same pan, cook the diced onion until translucent, then the garlic and ginger for a minute more.","Add the cumin, then the spinach purÃ©e. Cook only 5 minutes â€” long cooking dulls the colour and the flavour together.","Stir in the cream, garam masala, and the drained paneer. Warm through and serve."]'::jsonb),
  ('aloo-gobi', 'Aloo Gobi', 'Dry, not saucy. The cauliflower should have brown edges you can hear.', 'indian', '{"type":"tiktok","label":"TikTok"}'::jsonb, 35, 4, 46, array['weeknight', 'vegetarian']::text[], true, false, '2026-08-01', '[{"quantity":1,"unit":"head","item":"cauliflower","category":"produce"},{"quantity":3,"unit":"medium","item":"potatoes","category":"produce"},{"quantity":1,"unit":"medium","item":"yellow onion","category":"produce"},{"quantity":3,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":4,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":1,"unit":"tsp","item":"cumin seeds","category":"spices"},{"quantity":1,"unit":"tsp","item":"ground turmeric","category":"spices"},{"quantity":1,"unit":"tsp","item":"ground coriander","category":"spices"},{"quantity":0.5,"unit":"bunch","item":"cilantro","category":"produce"}]'::jsonb, '["Cut the cauliflower into florets and the potatoes into pieces the same size, so they finish together.","Heat the oil until it shimmers and add the cumin seeds. Wait for them to crackle â€” that is the temperature you want.","Add the potatoes first and let them colour for 5 minutes before you touch them.","Add the cauliflower, onion, garlic, and ginger with the turmeric and coriander. Toss to coat.","Cover and cook on low 15 minutes, shaking the pan rather than stirring so the florets stay whole.","Uncover, raise the heat, and let the last of the moisture go so the edges catch. Finish with cilantro."]'::jsonb),
  ('rajma-chawal', 'Rajma Chawal', 'The Sunday lunch of half of north India, and it reheats better than it cooks.', 'indian', '{"type":"blog","label":"seriouseats.com"}'::jsonb, 90, 4, 6, array['comfort', 'vegetarian']::text[], true, true, '2026-05-28', '[{"quantity":1.5,"unit":"cup","item":"red kidney beans","category":"pantry"},{"quantity":2,"unit":"medium","item":"yellow onion","category":"produce"},{"quantity":5,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":3,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":2,"unit":"tsp","item":"ground coriander","category":"spices"},{"quantity":1,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":1,"unit":"tsp","item":"Kashmiri chilli powder","category":"spices"},{"quantity":1.5,"unit":"cup","item":"basmati rice","category":"pantry"}]'::jsonb, '["Soak the kidney beans overnight, then simmer in fresh water 45 minutes until a bean crushes with no resistance between two fingers.","Brown the finely diced onion in the oil properly â€” 12 minutes at least. This is the entire backbone of the dish.","Add the garlic and ginger, then the coriander and chilli powder.","Add the tomatoes and cook until the oil separates out at the edges.","Tip in the beans with a cup of their cooking liquid. Simmer 20 minutes, mashing some against the pot so the gravy thickens on its own.","Start the basmati so it lands hot at the same time. Finish the rajma with garam masala."]'::jsonb),
  ('baingan-bharta', 'Baingan Bharta', 'Char the aubergine over a live flame or do not bother making it at all.', 'indian', '{"type":"instagram","label":"Instagram"}'::jsonb, 50, 4, 288, array['weeknight', 'vegetarian']::text[], true, false, '2026-07-12', '[{"quantity":2,"unit":"large","item":"aubergines","category":"produce"},{"quantity":1,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":4,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":2,"unit":"medium","item":"tomatoes","category":"produce"},{"quantity":2,"unit":"whole","item":"green chillies","category":"produce"},{"quantity":3,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":1,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":0.5,"unit":"bunch","item":"cilantro","category":"produce"}]'::jsonb, '["Rub the aubergines with oil and blacken them directly over a gas flame, turning until the skin collapses and the whole thing sags â€” 15 minutes. An oven broiler is second best.","Let them cool enough to handle, then peel away the burnt skin and chop the flesh roughly. Do not rinse it; you would be washing off the smoke.","Cook the diced onion in oil until golden, then add the garlic, ginger, and chillies.","Add the chopped tomatoes and cumin and cook until completely broken down.","Fold in the aubergine and cook 10 minutes, mashing as you go, until it tightens up.","Finish with garam masala and cilantro."]'::jsonb),
  ('masala-dosa', 'Masala Dosa', 'The batter ferments overnight. The cooking takes four minutes.', 'indian', '{"type":"youtube","label":"YouTube"}'::jsonb, 30, 4, 40, array['breakfast', 'vegetarian']::text[], false, true, '2026-08-14', '[{"quantity":2,"unit":"cup","item":"dosa batter","category":"pantry"},{"quantity":4,"unit":"medium","item":"potatoes","category":"produce"},{"quantity":1,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":2,"unit":"whole","item":"green chillies","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"tsp","item":"mustard seeds","category":"spices"},{"quantity":1,"unit":"tsp","item":"ground turmeric","category":"spices"},{"quantity":12,"unit":"whole","item":"curry leaves","category":"produce"},{"quantity":4,"unit":"tbsp","item":"neutral oil","category":"pantry"}]'::jsonb, '["Boil the potatoes until soft, then crush them roughly. Lumps are the point.","Heat oil and pop the mustard seeds, then add the curry leaves, sliced onion, chillies, and ginger.","Stir in the turmeric and the crushed potato with a splash of water and salt. Set this filling aside.","Get a flat pan properly hot, then wipe it with a halved onion dipped in oil â€” this is what stops the first dosa sticking.","Pour a ladle of batter in the centre and spiral outward with the back of the ladle in one continuous motion.","Drizzle oil around the edge and cook until the underside is lacquered and lifts on its own. Spoon filling down the middle and fold."]'::jsonb),
  ('pav-bhaji', 'Pav Bhaji', 'Mash it far more aggressively than feels correct.', 'indian', '{"type":"tiktok","label":"TikTok"}'::jsonb, 45, 4, 14, array['weeknight', 'comfort', 'vegetarian']::text[], true, false, '2026-06-22', '[{"quantity":4,"unit":"medium","item":"potatoes","category":"produce"},{"quantity":1,"unit":"small","item":"cauliflower","category":"produce"},{"quantity":1,"unit":"cup","item":"green peas","category":"produce"},{"quantity":2,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":3,"unit":"medium","item":"tomatoes","category":"produce"},{"quantity":1,"unit":"medium","item":"green bell pepper","category":"produce"},{"quantity":6,"unit":"tbsp","item":"unsalted butter","category":"dairy"},{"quantity":2,"unit":"tbsp","item":"pav bhaji masala","category":"spices"},{"quantity":1,"unit":"tsp","item":"Kashmiri chilli powder","category":"spices"},{"quantity":8,"unit":"piece","item":"pav rolls","category":"bakery"},{"quantity":1,"unit":"whole","item":"lemon","category":"produce"}]'::jsonb, '["Boil the potatoes, cauliflower, and peas together until everything is falling apart.","Melt half the butter and cook the diced onion and pepper until soft, then the tomatoes until they lose all structure.","Add the pav bhaji masala and chilli powder and fry it in the butter for a full minute.","Tip in the boiled vegetables and now mash relentlessly, adding splashes of the cooking water, until it is a coarse paste rather than a stew.","Simmer 10 minutes so it tightens and darkens. Adjust salt upward; it needs more than you think.","Split the pav, griddle them cut-side down in the remaining butter, and serve with raw onion and lemon."]'::jsonb),
  ('vegetable-biryani', 'Vegetable Biryani', 'Layered, not stirred. Stirring it makes very good rice and no biryani.', 'indian', '{"type":"youtube","label":"YouTube"}'::jsonb, 75, 6, 38, array['weekend', 'vegetarian']::text[], true, false, '2026-05-09', '[{"quantity":2,"unit":"cup","item":"basmati rice","category":"pantry"},{"quantity":3,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":2,"unit":"medium","item":"carrots","category":"produce"},{"quantity":1,"unit":"cup","item":"green beans","category":"produce"},{"quantity":1,"unit":"cup","item":"green peas","category":"produce"},{"quantity":1,"unit":"cup","item":"plain yogurt","category":"dairy"},{"quantity":6,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"tbsp","item":"biryani masala","category":"spices"},{"quantity":1,"unit":"pinch","item":"saffron","category":"spices"},{"quantity":0.5,"unit":"cup","item":"neutral oil","category":"pantry"},{"quantity":0.5,"unit":"bunch","item":"mint","category":"produce"}]'::jsonb, '["Slice the onions thin and fry them in oil in batches until genuinely brown and crisp. Drain on paper. These are not a garnish, they are a layer.","Soak the rice 30 minutes, then boil it in heavily salted water until it is 70% done â€” it should still snap in the middle. Drain immediately.","Cook the carrots, beans, and peas with the garlic, ginger, biryani masala, and yogurt until thick and clinging.","Warm the saffron in a little milk or water.","Layer: vegetables, then rice, then fried onions and mint. Repeat, finishing with rice. Spoon the saffron over in streaks so the colour stays uneven.","Seal the pot tightly, cook on the lowest possible heat for 25 minutes, then rest 10 minutes before opening.","Serve by digging down through all the layers with a spoon rather than stirring."]'::jsonb),
  ('paneer-tikka-masala', 'Paneer Tikka Masala', 'Char the paneer first. Sauce alone will not get you there.', 'indian', '{"type":"instagram","label":"Instagram"}'::jsonb, 50, 4, 10, array['weeknight', 'comfort', 'vegetarian']::text[], false, false, '2026-07-04', '[{"quantity":14,"unit":"oz","item":"paneer","category":"dairy"},{"quantity":1,"unit":"cup","item":"plain yogurt","category":"dairy"},{"quantity":1,"unit":"medium","item":"red bell pepper","category":"produce"},{"quantity":2,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":5,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":0.5,"unit":"cup","item":"heavy cream","category":"dairy"},{"quantity":1,"unit":"tbsp","item":"Kashmiri chilli powder","category":"spices"},{"quantity":2,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":3,"unit":"tbsp","item":"neutral oil","category":"pantry"}]'::jsonb, '["Marinate the cubed paneer and chunks of pepper and onion in the yogurt with half the chilli powder, garlic, and ginger for 20 minutes.","Sear them in a screaming hot pan until blackened in patches. Do not move them around; you are chasing char, not even cooking.","In the same pan, cook the remaining diced onion until soft, then the rest of the garlic and ginger.","Add the tomatoes and remaining chilli powder and cook down hard until the oil separates.","Blend the sauce smooth if you want it restaurant-style, or leave it rustic.","Return the charred paneer and vegetables, stir in the cream and garam masala, and simmer five minutes."]'::jsonb),
  ('butter-chicken', 'Butter Chicken', 'The sauce wants more butter than you are comfortable adding. Add it.', 'indian', '{"type":"youtube","label":"YouTube"}'::jsonb, 60, 4, 18, array['comfort']::text[], false, false, '2026-06-02', '[{"quantity":2,"unit":"lb","item":"boneless chicken thighs","category":"protein"},{"quantity":1,"unit":"cup","item":"plain yogurt","category":"dairy"},{"quantity":6,"unit":"tbsp","item":"unsalted butter","category":"dairy"},{"quantity":0.5,"unit":"cup","item":"heavy cream","category":"dairy"},{"quantity":1,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":6,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":1,"unit":"tbsp","item":"Kashmiri chilli powder","category":"spices"},{"quantity":2,"unit":"tsp","item":"garam masala","category":"spices"},{"quantity":1,"unit":"tsp","item":"dried fenugreek leaves","category":"spices"}]'::jsonb, '["Marinate the chicken in yogurt, half the garlic and ginger, and the chilli powder for at least 30 minutes.","Grill or sear the chicken hard until charred at the edges but not cooked through. It finishes in the sauce.","Cook the onion in butter until soft and pale gold, then add the remaining garlic and ginger.","Add the tomatoes and simmer 20 minutes until darkened and thick.","Blend the sauce completely smooth, then return it to the pan.","Add the chicken and its resting juices, the cream, and the rest of the butter. Simmer until the chicken is done.","Crush the fenugreek leaves between your palms over the pan at the very end. That smell is the one you are missing otherwise."]'::jsonb),
  ('lamb-rogan-josh', 'Lamb Rogan Josh', 'Kashmiri chilli for colour, not heat. Two and a half hours of patience.', 'indian', '{"type":"blog","label":"seriouseats.com"}'::jsonb, 150, 6, 354, array['weekend', 'comfort']::text[], true, true, '2026-04-18', '[{"quantity":3,"unit":"lb","item":"bone-in lamb shoulder","category":"protein"},{"quantity":1,"unit":"cup","item":"plain yogurt","category":"dairy"},{"quantity":2,"unit":"large","item":"yellow onion","category":"produce"},{"quantity":8,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"fresh ginger","category":"produce"},{"quantity":3,"unit":"tbsp","item":"Kashmiri chilli powder","category":"spices"},{"quantity":2,"unit":"tsp","item":"ground fennel","category":"spices"},{"quantity":1,"unit":"tsp","item":"ground cardamom","category":"spices"},{"quantity":4,"unit":"tbsp","item":"ghee","category":"dairy"},{"quantity":2,"unit":"whole","item":"bay leaves","category":"spices"}]'::jsonb, '["Brown the lamb hard in ghee in batches. Crowding the pot here costs you the entire dish.","Cook the sliced onion in the same fat until deep brown, then add the garlic and ginger.","Take the pot off the heat before adding the Kashmiri chilli powder â€” it scorches in seconds and turns bitter.","Whisk the yogurt and add it a spoonful at a time, stirring constantly so it does not split.","Return the lamb with the fennel, cardamom, bay, and just enough water to come halfway up.","Cover and cook at the barest simmer for two hours, until the meat pulls off the bone under a spoon.","Skim the red fat that rises, or do not. It is traditional either way. Better the next day."]'::jsonb),
  ('charred-corn-black-bean-tacos', 'Charred Corn and Black Bean Tacos', 'Built almost entirely from things already in the cupboard.', 'mexican', '{"type":"instagram","label":"Instagram"}'::jsonb, 25, 4, 76, array['weeknight', 'vegetarian']::text[], false, false, '2026-08-09', '[{"quantity":3,"unit":"ear","item":"corn","category":"produce"},{"quantity":1,"unit":"can","item":"black beans","category":"pantry"},{"quantity":1,"unit":"medium","item":"red onion","category":"produce"},{"quantity":2,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"olive oil","category":"pantry"},{"quantity":1,"unit":"whole","item":"lime","category":"produce"},{"quantity":0.5,"unit":"bunch","item":"cilantro","category":"produce"},{"quantity":8,"unit":"small","item":"corn tortillas","category":"bakery"},{"quantity":1,"unit":"tsp","item":"chili powder","category":"spices"},{"quantity":4,"unit":"oz","item":"cotija cheese","category":"dairy"}]'::jsonb, '["Strip the kernels from the cobs. Get a dry skillet properly hot and char them in a single layer, barely stirring, until blackened in spots.","Add olive oil, the diced red onion, and the garlic. Cook until the onion softens.","Stir in the drained beans and chili powder and warm through, mashing a few beans against the pan to bind it.","Squeeze in half the lime and season aggressively with salt.","Char the tortillas directly over a flame or in a dry pan.","Fill and top with cotija, cilantro, and the remaining lime cut into wedges."]'::jsonb),
  ('black-bean-enchiladas-verdes', 'Black Bean Enchiladas Verdes', 'The tomatillos do the work. The oven does the rest.', 'mexican', '{"type":"tiktok","label":"TikTok"}'::jsonb, 40, 4, 96, array['weeknight', 'vegetarian']::text[], false, false, '2026-07-21', '[{"quantity":1,"unit":"lb","item":"tomatillos","category":"produce"},{"quantity":2,"unit":"whole","item":"poblano peppers","category":"produce"},{"quantity":1,"unit":"medium","item":"white onion","category":"produce"},{"quantity":4,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"can","item":"black beans","category":"pantry"},{"quantity":12,"unit":"small","item":"corn tortillas","category":"bakery"},{"quantity":8,"unit":"oz","item":"Monterey Jack cheese","category":"dairy"},{"quantity":0.5,"unit":"bunch","item":"cilantro","category":"produce"},{"quantity":2,"unit":"tbsp","item":"neutral oil","category":"pantry"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":1,"unit":"whole","item":"lime","category":"produce"}]'::jsonb, '["Husk the tomatillos and broil them with the poblanos, half the onion, and the unpeeled garlic until blackened in patches â€” about 8 minutes.","Peel the garlic and blend everything with the cilantro, cumin, lime juice, and salt into a loose green sauce.","Warm the drained beans with the remaining diced onion and a little of the sauce, mashing lightly so they hold together in a tortilla.","Soften the tortillas in oil, a few seconds a side, so they roll without cracking.","Fill, roll, and pack them seam-side down in a baking dish. Pour the rest of the sauce over and cover with cheese.","Bake at 400Â°F for 20 minutes, until the sauce bubbles at the edges and the cheese browns in spots."]'::jsonb),
  ('chiles-rellenos', 'Chiles Rellenos', 'Sweat the peppers in a covered bowl and the skins come away in sheets.', 'mexican', '{"type":"youtube","label":"YouTube"}'::jsonb, 60, 4, 104, array['weekend', 'vegetarian']::text[], false, false, '2026-06-16', '[{"quantity":6,"unit":"whole","item":"poblano peppers","category":"produce"},{"quantity":12,"unit":"oz","item":"Oaxaca cheese","category":"dairy"},{"quantity":4,"unit":"large","item":"eggs","category":"dairy"},{"quantity":0.5,"unit":"cup","item":"all-purpose flour","category":"pantry"},{"quantity":4,"unit":"medium","item":"tomatoes","category":"produce"},{"quantity":1,"unit":"medium","item":"white onion","category":"produce"},{"quantity":3,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"cup","item":"neutral oil","category":"pantry"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"}]'::jsonb, '["Blister the poblanos over a flame until black all over, then seal them in a covered bowl for 10 minutes to steam.","Rub the skins off and cut a single slit down each one. Pull the seeds out through it and keep the stem attached.","Stuff each pepper with cheese and close the slit around it. Chill them 15 minutes so they hold shape.","Simmer the blended tomatoes, onion, garlic, and cumin into a thin sauce and keep it warm.","Whip the egg whites to stiff peaks, then fold the yolks back in gently. Dust each pepper in flour, then coat in the egg.","Fry in shallow oil, spooning hot oil over the top, until puffed and golden. Drain, then serve sitting in the warm sauce."]'::jsonb),
  ('birria-style-beef-tacos', 'Birria-Style Beef Tacos', 'A four-hour Sunday that pays you back in consommÃ©.', 'mexican', '{"type":"youtube","label":"YouTube"}'::jsonb, 240, 6, 344, array['weekend', 'comfort']::text[], false, false, '2026-05-03', '[{"quantity":3,"unit":"lb","item":"beef chuck roast","category":"protein"},{"quantity":4,"unit":"whole","item":"guajillo chiles","category":"spices"},{"quantity":2,"unit":"whole","item":"ancho chiles","category":"spices"},{"quantity":1,"unit":"large","item":"white onion","category":"produce"},{"quantity":6,"unit":"clove","item":"garlic","category":"produce"},{"quantity":2,"unit":"tbsp","item":"apple cider vinegar","category":"pantry"},{"quantity":1,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":2,"unit":"whole","item":"bay leaves","category":"spices"},{"quantity":12,"unit":"small","item":"corn tortillas","category":"bakery"},{"quantity":8,"unit":"oz","item":"Oaxaca cheese","category":"dairy"}]'::jsonb, '["Stem and seed the chiles, toast them in a dry pan until they smell nutty, then cover with boiling water for 20 minutes.","Blend the softened chiles with the garlic, half the onion, vinegar, cumin, and enough soaking liquid to make a smooth paste.","Brown the cubed chuck hard in a heavy pot, working in batches so it sears rather than steams.","Return all the beef, pour over the chile paste, add the bay leaves and water to just cover.","Braise covered at 300Â°F for three hours, until the beef shreds under a fork.","Shred the meat and skim the fat off the broth â€” keep that fat, it is the point.","Dip each tortilla in the red fat, griddle it, and fill with beef and Oaxaca cheese until crisp. Serve the broth alongside for dipping."]'::jsonb),
  ('crispy-chickpea-shakshuka', 'Crispy Chickpea Shakshuka', 'Breakfast that holds up perfectly well at nine at night.', 'other', '{"type":"tiktok","label":"TikTok"}'::jsonb, 30, 4, 8, array['weeknight', 'vegetarian']::text[], true, false, '2026-07-06', '[{"quantity":1,"unit":"can","item":"chickpeas","category":"pantry"},{"quantity":1,"unit":"can","item":"crushed tomatoes","category":"pantry"},{"quantity":1,"unit":"medium","item":"yellow onion","category":"produce"},{"quantity":4,"unit":"clove","item":"garlic","category":"produce"},{"quantity":1,"unit":"medium","item":"red bell pepper","category":"produce"},{"quantity":3,"unit":"tbsp","item":"olive oil","category":"pantry"},{"quantity":2,"unit":"tsp","item":"ground cumin","category":"spices"},{"quantity":1,"unit":"tsp","item":"smoked paprika","category":"spices"},{"quantity":4,"unit":"large","item":"eggs","category":"dairy"},{"quantity":4,"unit":"oz","item":"feta","category":"dairy"}]'::jsonb, '["Drain and dry the chickpeas thoroughly, then fry them in olive oil until they rattle and split. Scoop out half for the top later.","Add the sliced onion and pepper to the pan and cook until soft and sweet.","Stir in the garlic, cumin, and paprika and let them bloom for thirty seconds.","Pour in the tomatoes, season, and simmer 10 minutes until thick enough to hold a spoon trail.","Make four wells and crack an egg into each. Cover and cook until the whites set but the yolks still move.","Scatter over the reserved crispy chickpeas and crumbled feta."]'::jsonb),
  ('overnight-cinnamon-rolls', 'Overnight Cinnamon Rolls', 'The work happens the night before. Morning you just turns on the oven.', 'other', '{"type":"youtube","label":"YouTube"}'::jsonb, 150, 12, 12, array['baking', 'breakfast', 'vegetarian']::text[], false, true, '2026-05-19', '[{"quantity":4,"unit":"cup","item":"all-purpose flour","category":"pantry"},{"quantity":1,"unit":"packet","item":"active dry yeast","category":"pantry"},{"quantity":1,"unit":"cup","item":"whole milk","category":"dairy"},{"quantity":0.5,"unit":"cup","item":"granulated sugar","category":"pantry"},{"quantity":6,"unit":"tbsp","item":"unsalted butter","category":"dairy"},{"quantity":2,"unit":"large","item":"eggs","category":"dairy"},{"quantity":2,"unit":"tbsp","item":"ground cinnamon","category":"spices"},{"quantity":0.75,"unit":"cup","item":"light brown sugar","category":"pantry"},{"quantity":4,"unit":"oz","item":"cream cheese","category":"dairy"},{"quantity":1,"unit":"tsp","item":"kosher salt","category":"spices"}]'::jsonb, '["Warm the milk to blood temperature and stir in the yeast and a spoonful of the sugar. Wait ten minutes for it to foam.","Mix in the eggs, melted butter, remaining sugar, salt, and flour. Knead 8 minutes until smooth and slightly tacky.","Let it rise, covered, until doubled â€” roughly an hour.","Roll into a large rectangle. Spread with softened butter, then brown sugar and cinnamon right to the edges.","Roll up tightly, cut into twelve, and arrange in a buttered dish. Cover and refrigerate overnight.","In the morning, let them sit on the counter for an hour, then bake at 350Â°F for 25 to 30 minutes.","Beat the cream cheese with a little butter and sugar and spread it over while they are still warm."]'::jsonb),
  ('no-knead-rosemary-focaccia', 'No-Knead Rosemary Focaccia', 'The dough does all the work overnight while you do none of it.', 'other', '{"type":"blog","label":"kingarthurbaking.com"}'::jsonb, 90, 8, 108, array['baking', 'vegetarian']::text[], true, true, '2026-06-30', '[{"quantity":4,"unit":"cup","item":"bread flour","category":"pantry"},{"quantity":1,"unit":"packet","item":"instant yeast","category":"pantry"},{"quantity":2,"unit":"tsp","item":"kosher salt","category":"spices"},{"quantity":0.33,"unit":"cup","item":"olive oil","category":"pantry"},{"quantity":2,"unit":"sprig","item":"rosemary","category":"produce"},{"quantity":1,"unit":"tsp","item":"flaky sea salt","category":"spices"},{"quantity":2,"unit":"cup","item":"warm water","category":"pantry"}]'::jsonb, '["Stir the flour, yeast, salt, and warm water together into a shaggy, wet mess. No kneading â€” just make sure no dry flour remains.","Cover and refrigerate overnight, or leave at room temperature for four hours.","Pour a generous slick of olive oil into a sheet pan and tip the dough in. Turn it once to coat.","Let it relax and spread for an hour, until it fills the pan and wobbles.","Dimple it all over with oiled fingertips, right down to the pan. Scatter rosemary and flaky salt.","Bake at 450Â°F for 25 minutes, until the top is blistered and the underside is crisp."]'::jsonb),
  ('garlic-butter-shrimp-scampi', 'Garlic Butter Shrimp Scampi', 'Twenty minutes, one pan, and an indecent amount of garlic.', 'other', '{"type":"instagram","label":"Instagram"}'::jsonb, 20, 4, 24, array['weeknight', 'seafood']::text[], true, false, '2026-07-28', '[{"quantity":1,"unit":"lb","item":"large shrimp, peeled","category":"protein"},{"quantity":6,"unit":"clove","item":"garlic","category":"produce"},{"quantity":4,"unit":"tbsp","item":"unsalted butter","category":"dairy"},{"quantity":2,"unit":"tbsp","item":"olive oil","category":"pantry"},{"quantity":8,"unit":"oz","item":"linguine","category":"pantry"},{"quantity":1,"unit":"whole","item":"lemon","category":"produce"},{"quantity":0.25,"unit":"cup","item":"flat-leaf parsley","category":"produce"},{"quantity":0.5,"unit":"tsp","item":"red pepper flakes","category":"spices"},{"quantity":0.5,"unit":"cup","item":"dry white wine","category":"pantry"}]'::jsonb, '["Boil the linguine in well-salted water until just shy of al dente. Reserve a cup of the pasta water before draining.","Pat the shrimp dry and season with salt. Sear in olive oil over high heat, about 90 seconds a side, then move to a plate.","Lower the heat. Melt the butter, add the sliced garlic and red pepper flakes, and cook until the garlic is fragrant but not coloured â€” about a minute.","Pour in the white wine and scrape the pan. Let it reduce by half.","Return the shrimp and pasta to the pan with a splash of pasta water. Toss until the sauce clings.","Off the heat, finish with lemon juice, zest, and chopped parsley."]'::jsonb)
